```st
FUNCTION_BLOCK FB
VAR_INPUT
    enqueue  : BOOL;
    dequeue  : BOOL;
    reset    : BOOL;
    capacity : DINT;
END_VAR
VAR_OUTPUT
    elementCount : DINT := 0;
    status       : WORD := 16#0000;
END_VAR
VAR_IN_OUT
    item   : DINT;
    buffer : ARRAY[1..4] OF DINT;
END_VAR
VAR_STAT
    firstRun    : BOOL := TRUE;
    prevEnqueue : BOOL := FALSE;
    prevDequeue : BOOL := FALSE;
    head        : DINT := 1;
    tail        : DINT := 1;
END_VAR

VAR
    edgeEnqueue : BOOL;
    edgeDequeue : BOOL;
END_VAR

IF firstRun THEN
    head        := 1;
    tail        := 1;
    elementCount := 0;
    firstRun    := FALSE;
END_IF

edgeEnqueue := enqueue AND NOT prevEnqueue;
edgeDequeue := dequeue AND NOT prevDequeue;

IF reset THEN
    elementCount := 0;
    head := 1;
    tail := 1;
    status := 16#0000;
ELSE
    IF edgeEnqueue THEN
        IF elementCount < capacity THEN
            buffer[INT_TO_DINT(tail)] := item;
            tail := (tail MOD capacity) + 1;
            elementCount := elementCount + 1;
            status := 16#0000;
        ELSE
            status := 16#8002;
        END_IF
    END_IF

    IF edgeDequeue THEN
        IF elementCount > 0 THEN
            item := buffer[INT_TO_DINT(head)];
            head := (head MOD capacity) + 1;
            elementCount := elementCount - 1;
            status := 16#0000;
        ELSE
            status := 16#8001;
        END_IF
    END_IF
END_IF

prevEnqueue := enqueue;
prevDequeue := dequeue;
END_FUNCTION_BLOCK
```

